        { type: 'choice', topic: '摩擦力实验', text: '在丙图实验过程中，若木块所受拉力突然增大，则滑动摩擦力大小将____。<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image8/8-3-1.webp" style="max-width:100%;">', options: { A: '增大', B: '减小', C: '不变' }, answer: 'C', group: '8_3_1' },
        { type: 'choice', topic: '增大减小摩擦', text: '"安全出行，珍爱生命"。下列交通规则和安全规范中，为了减小摩擦的是（　　）', options: { A: '汽车轮胎上刻有凹凸不平的花纹', B: '骑自行车刹车时用力捏闸把', C: '高铁车轴处安装滚动轴承并加润滑油', D: '冰雪路面上汽车需加装防滑链' }, answer: 'C' },
        { type: 'choice', topic: '摩擦力', text: '如图所示，冰壶运动员两只鞋的鞋底不同，滑行时全身只由滑行鞋支撑，需要停下时用蹬冰鞋进行控制。冰壶运动员改变自身所受冰面摩擦力的主要方式是改变（　　）<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image8/8-3-3.webp" style="max-width:100%;">', options: { A: '接触面的粗糙程度', B: '接触面的面积', C: '对冰面的压力', D: '滑行的速度' }, answer: 'A' },
        { type: 'choice', topic: '摩擦力方向', text: '工人用刷子水平向右刷墙。在刷子向右运动的过程中，墙面施加给刷子的摩擦力方向是（　　）', options: { A: '水平向左', B: '水平向右', C: '竖直向上', D: '竖直向下' }, answer: 'A' },
        { type: 'choice', topic: '静摩擦力', text: '如图所示，用手握住一根重为5N的直铁棒，使铁棒沿竖直方向静止时，铁棒受到的摩擦力（　　）<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image8/8-3-5.webp" style="max-width:100%;">', options: { A: '等于5N', B: '大于5N', C: '小于5N', D: '随着手握棒的力增大而增大' }, answer: 'A' },
        { type: 'choice', topic: '静摩擦力', text: '如图所示，用手握住重为5N的瓶子处于静止状态，此时瓶子受到的摩擦力方向是____；增大手对瓶子握力，瓶子受到的摩擦力将____，如果往瓶子里加水后仍然静止，则瓶子受到的摩擦力将____。<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image8/8-3-6.webp" style="max-width:100%;">', options: { A: '竖直向下 不变 变大', B: '竖直向上 不变 变大', C: '竖直向下 变大 不变', D: '竖直向上 不变 变小' }, answer: 'B' }
