            // ----- 20.1 磁现象 磁场 -----
      '20.1': [
        { type: 'choice', topic: '磁现象', text: '在班级组织的"自制指南针"活动中，小伟同学将磁化后的缝衣针放在水中漂浮的树叶上，针尖指向树叶尖，待树叶静止后，树叶尖总是指向南方，如图所示。下列说法正确的是（　　）<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image20/20-1-1.webp" style="max-width:100%;">', options: { A: '磁化后的缝衣针尖端是S极', B: '磁化后的缝衣针周围存在磁感线', C: '磁化后的缝衣针尖指向地磁的南极', D: '若用磁铁N极靠近树叶尖，会相互排斥' }, answer: 'A' },
        { type: 'choice', topic: '磁现象', text: '据史料记载，秦始皇命人在阿房宫北阙门前修建了"磁石门"，以防行刺者入宫。下列物体能被"磁石门"检查出的是（　　）', options: { A: '陶罐', B: '木器', C: '铁器', D: '青铜器' }, answer: 'C' },
        { type: 'choice', topic: '磁现象', text: '如图所示，能自由转动的司南静止时，它的长柄指向南方，说明长柄是磁体的（　　）<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image20/20-1-3.webp" style="max-width:100%;">', options: { A: '南极', B: '北极', C: '东极', D: '西极' }, answer: 'A' },
        { type: 'choice', topic: '磁场与磁感线', text: '关于磁场和磁感线，下列说法正确的是（　　）', options: { A: '磁体周围的磁感线是从磁体的南极出来，回到它的北极', B: '磁场对放入其中的磁体有力的作用，当没放入磁体时，则既无力的作用也不存在磁场', C: '在磁场中画出磁感线处存在磁场，在磁感线间的空白处不存在磁场', D: '磁场虽然看不见，摸不到，在磁体周围确实存在着磁场' }, answer: 'D' },
        { type: 'choice', topic: '地磁场', text: '古人先将鱼形铁烧红，令铁鱼头尾指向南北，然后将其放入水中冷却，依靠地磁场获得磁性，再将其放入水中漂浮制成指南鱼，图中是它静止时的指向。则下列说法中正确的是（　　）<br><img src="https://pub-3827e3697a0b44428ab555d41c8d38f3.r2.dev/image20/20-1-5.webp" style="max-width:100%;">', options: { A: '指南鱼的磁感线真实存在', B: '指南鱼的腹部磁性最强', C: '指南鱼不会被其他磁体吸引', D: '指南鱼的鱼头应标注"N"极' }, answer: 'D' }
      ],
